-- JADARAH — 0026 exploratory tasks (generated by scripts/exploration/generate-sql.ts — do not edit by hand)
-- One short learning task per existing job category. Not employer assessments; never a hiring score. Idempotent.
insert into public.exploration_tasks (slug, category_id, minutes, title_en, title_ar, role_en, role_ar, daily_en, daily_ar,
  scenario_en, scenario_ar, deliverable_en, deliverable_ar, criteria, next_steps_en, next_steps_ar)
select v.slug, c.id, v.minutes, v.title_en, v.title_ar, v.role_en, v.role_ar, v.daily_en, v.daily_ar,
  v.scenario_en, v.scenario_ar, v.deliverable_en, v.deliverable_ar, v.criteria, v.next_en, v.next_ar
from (values
  ('explore-software', 'software', 20, 'Fix a checkout bug', 'إصلاح خلل في صفحة الدفع', 'Software engineers design, build and maintain the systems people use every day — and spend much of their time reading code, reasoning about failures and improving quality.', 'يصمم مهندسو البرمجيات الأنظمة التي يستخدمها الناس يوميًا ويبنونها ويصونونها، ويقضون جزءًا كبيرًا من وقتهم في قراءة الشيفرة وتحليل الأعطال وتحسين الجودة.',
   array['Read and review teammates'' code', 'Investigate and fix defects', 'Write tests and small features']::text[], array['قراءة شيفرة الزملاء ومراجعتها', 'تتبّع الأعطال وإصلاحها', 'كتابة الاختبارات والميزات الصغيرة']::text[], 'Customers report that the order total is sometimes wrong when a discount code is applied after changing the quantity. The function computes total = price × quantity, then applies the discount only when the code is entered, and caches the result.', 'يبلّغ العملاء أن إجمالي الطلب يكون خاطئًا أحيانًا عند إدخال رمز خصم بعد تغيير الكمية. الدالة تحسب الإجمالي = السعر × الكمية، ثم تطبّق الخصم فقط عند إدخال الرمز، وتحفظ النتيجة مؤقتًا.', 'Explain the likely cause, how you would reproduce it, your fix, and one test you would add.', 'اشرح السبب المحتمل، وكيف تعيد إنتاج المشكلة، والإصلاح المقترح، واختبارًا واحدًا ستضيفه.',
   '[{"key":"cause","en":"Identifies the stale cached total as the cause","ar":"يحدد أن الإجمالي المحفوظ مؤقتًا لا يُحدَّث","keywords":["cache","cached","stale","recalculat","مؤقت","إعادة الحساب","لا يتحدث","لا يُحدّث"]},{"key":"reproduce","en":"Describes concrete reproduction steps","ar":"يصف خطوات إعادة الإنتاج بوضوح","keywords":["reproduce","steps","change the quantity","خطوات","إعادة إنتاج","أغيّر الكمية","تغيير الكمية"]},{"key":"fix","en":"Proposes recalculating from inputs on every change","ar":"يقترح إعادة الحساب من المدخلات عند كل تغيير","keywords":["recompute","recalculate","every change","derive","invalidate","أعيد الحساب","عند كل تغيير","إبطال"]},{"key":"test","en":"Adds a regression test","ar":"يضيف اختبارًا يمنع تكرار الخلل","keywords":["test","assert","regression","اختبار","حالة اختبار"]}]'::jsonb, array['Practice debugging with unit tests in a language you know', 'Learn version control (Git) and code review etiquette', 'Build a small project and ask for a review']::text[], array['تدرّب على تتبّع الأخطاء باختبارات الوحدات بلغة تعرفها', 'تعلّم إدارة الإصدارات (Git) وأسلوب مراجعة الشيفرة', 'ابنِ مشروعًا صغيرًا واطلب مراجعته']::text[]),
  ('explore-data', 'data', 20, 'Explain a drop in weekly sales', 'تفسير انخفاض المبيعات الأسبوعية', 'Data analysts turn raw data into decisions: they clean data, look for patterns, test explanations and communicate findings clearly to non-specialists.', 'يحوّل محللو البيانات البيانات الخام إلى قرارات: ينظفون البيانات، ويبحثون عن الأنماط، ويختبرون التفسيرات، ويعرضون النتائج بوضوح لغير المتخصصين.',
   array['Write queries and clean datasets', 'Build dashboards and reports', 'Answer business questions with evidence']::text[], array['كتابة الاستعلامات وتنظيف البيانات', 'بناء لوحات المؤشرات والتقارير', 'الإجابة عن أسئلة العمل بالأدلة']::text[], 'A retail manager says: weekly sales fell 18% last week compared with the 8-week average. You have tables for orders (date, branch, channel, amount), promotions and store opening hours.', 'يقول مدير متجر: انخفضت المبيعات الأسبوعية 18٪ الأسبوع الماضي مقارنة بمتوسط 8 أسابيع. لديك جداول للطلبات (التاريخ، الفرع، القناة، المبلغ) والعروض الترويجية وساعات عمل الفروع.', 'Outline how you would investigate: what you check first, how you break the data down, and how you would present the answer.', 'وضّح كيف ستبحث: ماذا تتحقق منه أولًا، وكيف تقسّم البيانات، وكيف تعرض الإجابة.',
   '[{"key":"quality","en":"Checks data quality / completeness first","ar":"يتحقق أولًا من جودة البيانات واكتمالها","keywords":["missing","complete","quality","duplicate","data issue","ناقص","اكتمال","جودة","مكرر"]},{"key":"segment","en":"Breaks down by branch, channel or day","ar":"يقسّم حسب الفرع أو القناة أو اليوم","keywords":["branch","channel","segment","by day","breakdown","الفرع","القناة","تقسيم","حسب اليوم"]},{"key":"context","en":"Considers promotions, holidays or opening hours","ar":"يراعي العروض أو الإجازات أو ساعات العمل","keywords":["promotion","holiday","opening hours","season","عرض","إجازة","ساعات العمل","موسم"]},{"key":"communicate","en":"Plans a clear, concise presentation","ar":"يخطط لعرض واضح ومختصر","keywords":["chart","summary","dashboard","recommend","رسم","ملخص","لوحة","توصية"]}]'::jsonb, array['Learn SQL aggregation and joins', 'Practice a dashboard tool with a public dataset', 'Write a one-page insight summary']::text[], array['تعلّم التجميع والربط في SQL', 'تدرّب على أداة لوحات مؤشرات ببيانات عامة', 'اكتب ملخص نتائج من صفحة واحدة']::text[]),
  ('explore-ai', 'ai', 20, 'Evaluate a text classifier', 'تقييم نموذج تصنيف نصوص', 'Machine-learning engineers build models that learn from data, and spend much of their time on data preparation, evaluation and responsible deployment.', 'يبني مهندسو تعلم الآلة نماذج تتعلم من البيانات، ويقضون معظم وقتهم في تجهيز البيانات وتقييم النماذج ونشرها بمسؤولية.',
   array['Prepare and label training data', 'Train and evaluate models', 'Monitor models in production']::text[], array['تجهيز بيانات التدريب ووسمها', 'تدريب النماذج وتقييمها', 'مراقبة النماذج بعد النشر']::text[], 'A model that routes customer complaints into 5 categories reports 92% accuracy. 70% of complaints belong to one category, and agents say urgent safety complaints are often misrouted.', 'نموذج يوجّه شكاوى العملاء إلى 5 فئات يحقق دقة 92٪. 70٪ من الشكاوى تنتمي إلى فئة واحدة، ويقول الموظفون إن شكاوى السلامة العاجلة تُوجَّه خطأً كثيرًا.', 'Explain whether 92% accuracy is reassuring, which metrics you would use instead, and what you would change.', 'اشرح هل دقة 92٪ مطمئنة، وما المقاييس التي ستستخدمها بدلًا منها، وما الذي ستغيّره.',
   '[{"key":"imbalance","en":"Recognises class imbalance","ar":"يدرك عدم توازن الفئات","keywords":["imbalance","majority","skewed","عدم توازن","الفئة الغالبة","غير متوازن"]},{"key":"metrics","en":"Uses per-class precision/recall or a confusion matrix","ar":"يستخدم الدقة والاستدعاء لكل فئة أو مصفوفة الالتباس","keywords":["recall","precision","f1","confusion","استدعاء","مصفوفة","لكل فئة"]},{"key":"risk","en":"Prioritises the cost of missing safety complaints","ar":"يعطي الأولوية لكلفة إغفال شكاوى السلامة","keywords":["safety","cost","critical","threshold","السلامة","الكلفة","حرج","عتبة"]},{"key":"action","en":"Proposes concrete improvements (data, weighting, review)","ar":"يقترح تحسينات عملية (بيانات، أوزان، مراجعة بشرية)","keywords":["more data","weight","human review","resample","بيانات إضافية","أوزان","مراجعة بشرية"]}]'::jsonb, array['Study evaluation metrics beyond accuracy', 'Train a simple classifier on a public dataset', 'Read about responsible AI and human oversight']::text[], array['ادرس مقاييس التقييم أبعد من الدقة', 'درّب مصنّفًا بسيطًا على بيانات عامة', 'اقرأ عن الذكاء الاصطناعي المسؤول والإشراف البشري']::text[]),
  ('explore-security', 'security', 20, 'Triage a suspicious sign-in alert', 'فرز تنبيه دخول مشبوه', 'Security analysts protect organisations by monitoring alerts, investigating incidents and reducing risk — often in a Security Operations Centre (SOC).', 'يحمي محللو الأمن السيبراني المنظمات عبر مراقبة التنبيهات والتحقيق في الحوادث وتقليل المخاطر، وغالبًا ضمن مركز عمليات الأمن (SOC).',
   array['Review security alerts', 'Investigate logs and incidents', 'Recommend controls and document findings']::text[], array['مراجعة التنبيهات الأمنية', 'التحقيق في السجلات والحوادث', 'اقتراح الضوابط وتوثيق النتائج']::text[], 'An alert shows a finance employee signing in at 03:10 from a new country, 20 minutes after a sign-in from Riyadh. Two failed MFA prompts preceded a successful one.', 'يظهر تنبيه بدخول موظف في المالية الساعة 03:10 من دولة جديدة، بعد 20 دقيقة من دخول من الرياض. سبقت الدخول الناجح محاولتان فاشلتان للتحقق متعدد العوامل.', 'Describe how you would assess this alert, what you would check, and your immediate containment steps.', 'صِف كيف تقيّم هذا التنبيه، وما الذي ستتحقق منه، وخطوات الاحتواء الفورية.',
   '[{"key":"travel","en":"Notes impossible travel","ar":"يلاحظ استحالة التنقل بين الموقعين","keywords":["impossible travel","two locations","استحالة","موقعين","تنقل"]},{"key":"mfa","en":"Considers MFA fatigue / push bombing","ar":"يأخذ في الحسبان إغراق طلبات التحقق متعدد العوامل","keywords":["mfa fatigue","push","prompt","bombing","إرهاق","طلبات التحقق","إغراق"]},{"key":"contain","en":"Proposes containment (revoke sessions, reset, disable)","ar":"يقترح الاحتواء (إلغاء الجلسات، إعادة التعيين، التعطيل)","keywords":["revoke","reset","disable","block","isolate","إلغاء الجلسات","إعادة تعيين","تعطيل","حظر"]},{"key":"verify","en":"Verifies with the user and documents","ar":"يتحقق مع الموظف ويوثّق","keywords":["contact the user","verify","document","ticket","التواصل مع","التحقق","توثيق","تذكرة"]}]'::jsonb, array['Learn common attack techniques (e.g. MITRE ATT&CK)', 'Practice log analysis with free labs', 'Study incident response basics']::text[], array['تعرّف على أساليب الهجوم الشائعة (مثل MITRE ATT&CK)', 'تدرّب على تحليل السجلات في مختبرات مجانية', 'ادرس أساسيات الاستجابة للحوادث']::text[]),
  ('explore-cloud', 'cloud', 20, 'Plan for a traffic spike', 'التخطيط لارتفاع مفاجئ في الزيارات', 'Cloud and infrastructure engineers keep systems available, secure and cost-effective — automating deployments and planning capacity.', 'يحافظ مهندسو السحابة والبنية التحتية على توفر الأنظمة وأمنها وكفاءة تكلفتها، ويؤتمتون النشر ويخططون للسعة.',
   array['Automate infrastructure and deployments', 'Monitor availability and cost', 'Respond to incidents']::text[], array['أتمتة البنية التحتية والنشر', 'مراقبة التوفر والتكلفة', 'الاستجابة للحوادث']::text[], 'A ticketing website expects 10× normal traffic for two hours when a popular event goes on sale. It runs on two servers and one database today.', 'يتوقع موقع لبيع التذاكر 10 أضعاف الزيارات المعتادة لمدة ساعتين عند طرح فعالية مشهورة. يعمل حاليًا على خادمين وقاعدة بيانات واحدة.', 'Describe how you would prepare: scaling, protecting the database, testing and monitoring.', 'صِف كيف ستستعد: التوسع، وحماية قاعدة البيانات، والاختبار، والمراقبة.',
   '[{"key":"scale","en":"Uses autoscaling or pre-scaling","ar":"يستخدم التوسع التلقائي أو المسبق","keywords":["autoscal","scale out","more servers","load balancer","توسع","موازن","خوادم إضافية"]},{"key":"db","en":"Protects the database (cache, replicas, queue)","ar":"يحمي قاعدة البيانات (تخزين مؤقت، نسخ، طوابير)","keywords":["cache","replica","queue","connection pool","تخزين مؤقت","نسخ قراءة","طابور"]},{"key":"test","en":"Load-tests in advance","ar":"يجري اختبار حمل مسبقًا","keywords":["load test","stress","rehears","اختبار حمل","اختبار ضغط"]},{"key":"monitor","en":"Sets up monitoring, alerts and a rollback plan","ar":"يجهز المراقبة والتنبيهات وخطة تراجع","keywords":["monitor","alert","rollback","dashboard","مراقبة","تنبيه","تراجع"]}]'::jsonb, array['Learn the basics of one major cloud provider', 'Practice infrastructure as code', 'Study caching and load balancing']::text[], array['تعلّم أساسيات أحد مزودي السحابة الرئيسيين', 'تدرّب على البنية التحتية كشيفرة', 'ادرس التخزين المؤقت وموازنة الأحمال']::text[]),
  ('explore-design', 'design', 20, 'Simplify a government-service form', 'تبسيط نموذج خدمة إلكترونية', 'Product designers shape how people experience digital services — researching needs, designing flows and testing with real users.', 'يصمم مصممو المنتجات تجربة الناس مع الخدمات الرقمية: يبحثون في الاحتياجات، ويصممون المسارات، ويختبرونها مع مستخدمين حقيقيين.',
   array['Interview and observe users', 'Design flows and interfaces', 'Test prototypes and iterate']::text[], array['مقابلة المستخدمين وملاحظتهم', 'تصميم المسارات والواجهات', 'اختبار النماذج الأولية وتحسينها']::text[], 'An online permit form has 34 fields on one page. 60% of users abandon it, most often at the ''supporting documents'' section. Many users complete it on mobile.', 'نموذج تصريح إلكتروني يحوي 34 حقلًا في صفحة واحدة. يتركه 60٪ من المستخدمين، وغالبًا عند قسم «المستندات الداعمة». كثير منهم يستخدمون الجوال.', 'Propose how you would redesign the experience and how you would know it worked.', 'اقترح كيف ستعيد تصميم التجربة، وكيف ستعرف أنها نجحت.',
   '[{"key":"research","en":"Starts by understanding why users abandon","ar":"يبدأ بفهم سبب ترك المستخدمين","keywords":["interview","research","observe","why","مقابلة","بحث","ملاحظة","لماذا"]},{"key":"structure","en":"Breaks the form into steps and removes fields","ar":"يقسّم النموذج إلى خطوات ويحذف الحقول غير الضرورية","keywords":["steps","remove","fewer fields","progress","خطوات","حذف","حقول أقل","تقدم"]},{"key":"mobile","en":"Designs for mobile and accessibility","ar":"يصمم للجوال وإمكانية الوصول","keywords":["mobile","accessib","upload","الجوال","إمكانية الوصول","رفع"]},{"key":"measure","en":"Defines success metrics and testing","ar":"يحدد مقاييس النجاح والاختبار","keywords":["completion rate","test","metric","a/b","معدل الإكمال","اختبار","مقياس"]}]'::jsonb, array['Learn usability-testing basics', 'Practice in a design tool with a real service', 'Study accessibility guidelines (WCAG)']::text[], array['تعلّم أساسيات اختبار قابلية الاستخدام', 'تدرّب على أداة تصميم بخدمة حقيقية', 'ادرس إرشادات إمكانية الوصول (WCAG)']::text[]),
  ('explore-product', 'product', 20, 'Prioritise a product backlog', 'ترتيب أولويات قائمة مهام منتج', 'Product managers decide what to build and why — balancing user needs, business goals and engineering effort, and aligning the team.', 'يقرر مديرو المنتجات ماذا يُبنى ولماذا، موازنين بين احتياجات المستخدمين وأهداف العمل وجهد الفريق التقني، ويوحّدون الفريق حول الأهداف.',
   array['Talk with users and stakeholders', 'Write requirements and prioritise', 'Track outcomes after release']::text[], array['الحديث مع المستخدمين وأصحاب المصلحة', 'كتابة المتطلبات وترتيب الأولويات', 'متابعة النتائج بعد الإطلاق']::text[], 'A food-delivery app team can ship only one item this month: (a) Apple Pay, requested by sales; (b) fixing late-order notifications, the top support complaint; (c) a new loyalty programme, requested by the CEO.', 'يستطيع فريق تطبيق توصيل طعام إطلاق عنصر واحد فقط هذا الشهر: (أ) الدفع عبر Apple Pay بطلب المبيعات؛ (ب) إصلاح تنبيهات الطلبات المتأخرة، أكثر شكوى للدعم؛ (ج) برنامج ولاء جديد بطلب الرئيس التنفيذي.', 'Choose one, justify it with evidence you would gather, and explain how you would communicate the decision.', 'اختر عنصرًا، وبرّر اختيارك بالأدلة التي ستجمعها، واشرح كيف ستبلغ القرار.',
   '[{"key":"evidence","en":"Uses data/evidence to decide","ar":"يعتمد على البيانات والأدلة","keywords":["data","evidence","metric","impact","بيانات","أدلة","أثر","مقياس"]},{"key":"framework","en":"Weighs impact against effort","ar":"يوازن بين الأثر والجهد","keywords":["effort","impact","rice","value","cost","الجهد","القيمة","التكلفة"]},{"key":"users","en":"Considers user and business outcomes","ar":"يراعي نتائج المستخدم والعمل","keywords":["user","retention","churn","customer","المستخدم","الاحتفاظ","العميل"]},{"key":"communicate","en":"Plans stakeholder communication","ar":"يخطط للتواصل مع أصحاب المصلحة","keywords":["stakeholder","communicat","explain","roadmap","أصحاب المصلحة","تواصل","خارطة"]}]'::jsonb, array['Learn prioritisation frameworks', 'Write a one-page product brief', 'Practice user interviews']::text[], array['تعرّف على أطر ترتيب الأولويات', 'اكتب وثيقة منتج من صفحة واحدة', 'تدرّب على مقابلات المستخدمين']::text[]),
  ('explore-finance', 'finance', 20, 'Review a department budget variance', 'مراجعة انحراف ميزانية إدارة', 'Financial analysts help organisations plan and control money — building budgets, analysing variances and advising on decisions.', 'يساعد المحللون الماليون المنظمات على تخطيط الأموال وضبطها: إعداد الميزانيات وتحليل الانحرافات وتقديم المشورة للقرارات.',
   array['Prepare budgets and forecasts', 'Analyse variances and reports', 'Advise managers on costs']::text[], array['إعداد الميزانيات والتوقعات', 'تحليل الانحرافات والتقارير', 'تقديم المشورة للمديرين حول التكاليف']::text[], 'The marketing department spent SAR 1.3m in Q2 against a budget of SAR 1.0m. Revenue from campaigns rose 12%. Finance must report to leadership next week.', 'أنفقت إدارة التسويق 1.3 مليون ريال في الربع الثاني مقابل ميزانية مليون ريال. ارتفعت إيرادات الحملات 12٪. يجب أن ترفع الإدارة المالية تقريرًا للقيادة الأسبوع القادم.', 'Explain how you would analyse the variance, what questions you would ask, and what you would recommend.', 'اشرح كيف ستحلل الانحراف، وما الأسئلة التي ستطرحها، وما توصيتك.',
   '[{"key":"variance","en":"Quantifies the variance (30% over budget)","ar":"يحسب الانحراف (تجاوز 30٪)","keywords":["30%","300","variance","over budget","٣٠","30٪","انحراف","تجاوز"]},{"key":"drivers","en":"Breaks spend into drivers","ar":"يحلل الإنفاق إلى مسبباته","keywords":["driver","breakdown","line item","channel","مسببات","تفصيل","بند"]},{"key":"roi","en":"Compares cost with return","ar":"يقارن التكلفة بالعائد","keywords":["roi","return","revenue","cost per","العائد","الإيرادات","تكلفة"]},{"key":"recommend","en":"Gives a clear recommendation and controls","ar":"يقدم توصية واضحة وضوابط","keywords":["recommend","approval","control","forecast","توصية","اعتماد","ضوابط","توقعات"]}]'::jsonb, array['Strengthen spreadsheet modelling', 'Learn variance analysis and forecasting', 'Read published financial statements']::text[], array['طوّر مهارات النمذجة في الجداول', 'تعلّم تحليل الانحرافات والتنبؤ', 'اقرأ قوائم مالية منشورة']::text[]),
  ('explore-engineering', 'engineering', 20, 'Investigate cracks in a site slab', 'التحقيق في تشققات بلاطة موقع إنشائي', 'Civil and industrial engineers plan, design and supervise physical works — infrastructure, buildings and plants — with safety and quality at the centre.', 'يخطط المهندسون المدنيون والصناعيون للأعمال الإنشائية والصناعية ويصممونها ويشرفون عليها، من البنية التحتية إلى المباني والمصانع، مع جعل السلامة والجودة في المقدمة.',
